import React, { useEffect, useRef } from 'react';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';

function TerminalComponent({ containerId }) {
  const terminalRef = useRef(null);
  const socketRef = useRef(null);
  const terminal = useRef(null);
  const fitAddon = useRef(new FitAddon()).current; // Ensure FitAddon is only created once

  // Function to establish the WebSocket connection
  const initializeWebSocket = () => {
    const socket = new WebSocket('ws://localhost:3001');
    socketRef.current = socket;

    socket.onopen = () => {
      console.log('WebSocket connection established');
      socket.send(JSON.stringify({ containerId, cmd: '/bin/sh' })); // Start a shell in the container
    };

    // Handle incoming messages from the backend
    socket.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.output) {
        terminal.current.write(message.output);
      } else if (message.error) {
        terminal.current.write(`\x1B[31m${message.error}\x1B[0m`); // Display errors in red
      } else if (message.message) {
        terminal.current.write(message.message);
      }
    };

    socket.onerror = (error) => {
      console.error('WebSocket error:', error);
      // Optionally, handle reconnection logic here if needed
    };

    socket.onclose = () => {
      console.log('WebSocket connection closed');
      // Optionally, handle reconnection logic here if needed
    };

    return socket;
  };

  useEffect(() => {
    if (!terminalRef.current) return;

    // Initialize xterm.js terminal
    terminal.current = new Terminal();
    terminal.current.loadAddon(fitAddon);
    terminal.current.open(terminalRef.current);

    // Fit the terminal after it has been opened
    fitAddon.fit();

    // Establish WebSocket connection
    const socket = initializeWebSocket();

    // Send terminal input to WebSocket
    terminal.current.onData((input) => {
      // Check if the WebSocket is open before sending data
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(JSON.stringify({ containerId, cmd: input }));
      } else {
        console.warn('WebSocket is not open. Message not sent:', input);
        // Optionally, retry WebSocket connection if not open
        if (socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) {
          // Retry logic, or show a user-friendly message
          console.log('Retrying WebSocket connection...');
          socket.close(); // Close the current socket and try to reconnect
          initializeWebSocket(); // Re-initialize the WebSocket
        }
      }
    });

    // Handle terminal resize on window resize
    const handleResize = () => {
      if (terminalRef.current) {
        fitAddon.fit();
      }
    };

    window.addEventListener('resize', handleResize);

    // Cleanup on component unmount
    return () => {
      if (socket.readyState === WebSocket.OPEN) {
        socket.close();
      }
      terminal.current.dispose();
      window.removeEventListener('resize', handleResize);
    };
  }, [containerId, fitAddon]);

  return <div ref={terminalRef} style={{ width: '100%', height: '800px' }} />;
}

export default TerminalComponent;
